const runnerBase = process.env.AUTOMATION_RUNNER_BASE_URL;
const runnerToken = process.env.AUTOMATION_RUNNER_TOKEN;
if (!runnerBase) throw new Error('AUTOMATION_RUNNER_BASE_URL is not configured');
const headers = {
  'Content-Type': 'application/json',
  ...(runnerToken ? { Authorization: `Bearer ${runnerToken}` } : {}),
};

const healthResponse = await fetch(`${runnerBase}/services/health`, { headers });
if (!healthResponse.ok) throw new Error(`services/health failed: ${healthResponse.status}`);
const health = await healthResponse.json();

let restartResult = null;
const restartTarget = health.failingServices.find((service) => health.services[service]?.restartable);
if (restartTarget) {
  const restartResponse = await fetch(`${runnerBase}/jobs`, {
    method: 'POST',
    headers,
    body: JSON.stringify({ action: 'restart_service', mode: 'sync', args: [restartTarget] }),
  });
  const rawRestart = await restartResponse.text();
  restartResult = rawRestart ? JSON.parse(rawRestart) : null;
}

const reportRelativePath = `health-monitor/${new Date().toISOString().replace(/[:]/g, '-')}.md`;
const reportContent = [
  '# Automation Health Monitor',
  '',
  `Generated: ${new Date().toISOString()}`,
  `Healthy: ${health.ok ? 'yes' : 'no'}`,
  `Restart Target: ${restartTarget || 'none'}`,
  '',
  '## Health Snapshot',
  '',
  '```json',
  JSON.stringify(health, null, 2),
  '```',
  '',
  '## Restart Result',
  '',
  restartResult ? '```json\n' + JSON.stringify(restartResult, null, 2) + '\n```' : 'No restart attempted.',
].join('\n');

const writeResponse = await fetch(`${runnerBase}/reports/write`, {
  method: 'POST',
  headers,
  body: JSON.stringify({ relativePath: reportRelativePath, content: reportContent }),
});
if (!writeResponse.ok) throw new Error(`reports/write failed: ${writeResponse.status}`);

await fetch(`${runnerBase}/context/health-monitor`, {
  method: 'PUT',
  headers,
  body: JSON.stringify({ value: { health, restartResult, reportRelativePath } }),
});

return [{ json: { generatedAt: new Date().toISOString(), health, restartTarget, restartResult, reportRelativePath } }];
